void countdown(int n) {
if (n > 0) {
cout << n 
  << " ";
countdown(n - 1);
}
}
int main() {
countdown(5);
}

---

int factorial(int n) {
if (n > 1) {
return n * factorial(n - 1);
} else {
return 1;
}
}
int main() {
cout << "Factorial of 5 is " << factorial(5);
return 0;
}
